python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
ws=wb['Task']
ranges = [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]
missing=[]
print('Formula cell verification (data_only=False):')
for r1,r2 in ranges:
    for r in range(r1,r2+1):
        vals=[]
        for c in range(8,13):
            coord=f'{get_column_letter(c)}{r}'
            v=ws[coord].value
            vals.append(f'{coord}={v!r}')
            if not (isinstance(v,str) and v.startswith('=')):
                missing.append((coord,v))
        print(' | '.join(vals))
print('\nFormula strings missing/non-formula count:', len(missing))
if missing:
    print(missing)

# Formula expectations check
expected_errors=[]
for r in list(range(12,18))+list(range(19,25))+list(range(26,32)):
    for c in range(8,13):
        col=get_column_letter(c)
        exp=f'=INDEX(Data!$H$21:$L$38, MATCH($D{r}, Data!$D$21:$D$38, 0), MATCH({col}$10, Data!$H$4:$L$4, 0))'
        if ws.cell(r,c).value != exp:
            expected_errors.append((ws.cell(r,c).coordinate, ws.cell(r,c).value, exp))
for idx, r in enumerate(range(35,41)):
    for c in range(8,13):
        col=get_column_letter(c)
        exp=f'=({col}{12+idx}-{col}{19+idx})/{col}{26+idx}*100'
        if ws.cell(r,c).value != exp:
            expected_errors.append((ws.cell(r,c).coordinate, ws.cell(r,c).value, exp))
for c in range(8,13):
    col=get_column_letter(c)
    exps={42:f'=MIN({col}35:{col}40)',43:f'=MAX({col}35:{col}40)',44:f'=MEDIAN({col}35:{col}40)',45:f'=AVERAGE({col}35:{col}40)',46:f'=PERCENTILE({col}35:{col}40,0.25)',47:f'=PERCENTILE({col}35:{col}40,0.75)',50:f'=SUMPRODUCT({col}35:{col}40, {col}26:{col}31) / SUM({col}26:{col}31)'}
    for r, exp in exps.items():
        if ws.cell(r,c).value != exp:
            expected_errors.append((ws.cell(r,c).coordinate, ws.cell(r,c).value, exp))
print('Exact expected formula mismatch count:', len(expected_errors))
if expected_errors:
    for e in expected_errors[:20]: print(e)

# data_only optional check: openpyxl won't calculate formulas; cached values may be None, so report count only.
wbv=load_workbook(path, data_only=True)
wsv=wbv['Task']
none_count=0
checked=0
for r1,r2 in ranges:
    for r in range(r1,r2+1):
        for c in range(8,13):
            checked += 1
            if wsv.cell(r,c).value is None:
                none_count += 1
print(f'data_only=True cached None count: {none_count} of {checked} (openpyxl does not calculate formulas)')
if missing or expected_errors:
    raise SystemExit(1)
PY
